	/**  Bytes to download. */
	download_size: number,
	/**  Bytes on disk once installed. */
	disk_size: number,
	/**  Bytes held. */
	held: number,
	/**  Install state. */
	installed: Installed,
	/**  It is downloading now. */
	downloading: boolean,
	/**  Its setting. */
	on: boolean,
	/**  Why Remove is refused now; `null` when it is not. */
